export const GetDashboardStatsResponse = zod.object({
  totalCases: zod.number(),
  activeCases: zod.number(),
  completedCases: zod.number(),
  pendingForms: zod.number(),
  overdueForms: zod.number(),
  casesByPhase: zod.record(zod.string(), zod.number()),
  recentCases: zod.array(
    zod.object({
      id: zod.string(),
      studentName: zod.string(),
      dob: zod.string(),
      school: zod.string(),
      grade: zod.string().optional(),
      languagePreference: zod.enum(["english", "mandarin", "cantonese"]),
      referralReason: zod.string().optional(),
      caseStatus: zod.enum(["active", "on_hold", "completed", "archived"]),
      caseMode: zod.enum(["live", "test"]).optional(),
      currentPhase: zod.enum([
        "pre_commitment",
        "intake",
        "setup",
        "forms",
        "assessment",
        "scoring",
        "report",
        "debrief",
        "complete",
      ]),
      progressPercentage: zod
        .number()
        .min(getDashboardStatsResponseRecentCasesItemProgressPercentageMin)
        .max(getDashboardStatsResponseRecentCasesItemProgressPercentageMax),
      riskLevel: zod.enum(["low", "moderate", "high"]).nullish(),
      assignedLeadId: zod.string().nullish(),
      assignedPsychId: zod.string().nullish(),
      parentName: zod.string().nullish(),
      parentEmail: zod.string().nullish(),
      parentPhone: zod.string().nullish(),
      consentObtained: zod.boolean(),
      createdAt: zod.date(),
      updatedAt: zod.date(),
    }),
  ),
});

/**
 * @summary List all assessment batteries
 */
export const ListBatteriesResponseItem = zod.object({
  id: zod.string(),
  name: zod.string(),
  description: zod.string(),
  toolIds: zod.array(zod.string()),
  isRemyndOwned: zod.boolean(),
  domains: zod.array(zod.string()),
  scoringNotes: zod.string().nullish(),
});
export const ListBatteriesResponse = zod.array(ListBatteriesResponseItem);

/**
 * @summary Get a single battery with its tools
 */
export const GetBatteryParams = zod.object({
  id: zod.coerce.string(),
});

export const GetBatteryResponse = zod
  .object({
    id: zod.string(),
    name: zod.string(),
    description: zod.string(),
    toolIds: zod.array(zod.string()),
    isRemyndOwned: zod.boolean(),
    domains: zod.array(zod.string()),
    scoringNotes: zod.string().nullish(),
  })
  .and(
    zod.object({
      tools: zod.array(
        zod.object({
          id: zod.string(),
          name: zod.string(),
          description: zod.string(),
          domains: zod.array(zod.string()),
        }),
      ),
    }),
  );

/**
 * @summary Update the tool list for a battery
 */
export const UpdateBatteryToolsParams = zod.object({
  id: zod.coerce.string(),
});

export const UpdateBatteryToolsBody = zod.object({
  toolIds: zod.array(zod.string()),
});

export const UpdateBatteryToolsResponse = zod.object({
  id: zod.string(),
  name: zod.string(),
  description: zod.string(),
  toolIds: zod.array(zod.string()),
  isRemyndOwned: zod.boolean(),
  domains: zod.array(zod.string()),
  scoringNotes: zod.string().nullish(),
});

/**
 * @summary Assign all tools in a battery to a case (bulk create assignments)
 */
export const AssignBatteryParams = zod.object({
  caseId: zod.coerce.string(),
  batteryId: zod.coerce.string(),
});

export const assignBatteryBodyRespondentTypeDefault = `parent`;

export const AssignBatteryBody = zod.object({
  respondentType: zod.string().default(assignBatteryBodyRespondentTypeDefault),
  respondentLabel: zod.string().optional(),
  assignedToName: zod.string().optional(),
  assignedToEmail: zod.string().optional(),
  dueDate: zod.date().nullish(),
});

/**
 * @summary Get CDP Battery composite profile for a case
 */
export const GetCdpProfileParams = zod.object({
  caseId: zod.coerce.string(),
});

export const GetCdpProfileResponse = zod.object({
  caseId: zod.string(),
  forms: zod.array(
    zod.object({
      toolId: zod.string(),
      toolName: zod.string(),
      status: zod.enum(["not_assigned", "pending", "completed"]),
      assignments: zod.array(
        zod.object({
          id: zod.string(),
          status: zod.string(),
          respondentType: zod.string(),
          respondentLabel: zod.string().nullish(),
          assignedToName: zod.string().nullish(),
          assignedToEmail: zod.string().nullish(),
        }),
      ),
      score: zod
        .object({
          rawScore: zod.number(),
          domainScores: zod.record(zod.string(), zod.number()),
          normalizedScores: zod.record(zod.string(), zod.number()),
          scoredAt: zod.string().nullish(),
        })
        .nullish(),
      scoringConfig: zod.object({}).passthrough().nullish(),
    }),
  ),
});

/**
 * @summary Get source-separated Chinese Literacy submissions and latest comparison draft
 */
export const GetChineseLiteracyDashboardParams = zod.object({
  caseId: zod.coerce.string(),
});

export const GetChineseLiteracyDashboardResponse = zod.object({
  caseId: zod.string(),
  administrations: zod.array(
    zod.object({
      assignmentId: zod.string(),
      instrumentKey: zod.string(),
      formName: zod.string(),
      setting: zod.string(),
      respondentType: zod.string(),
      respondentLabel: zod.string(),
      status: zod.string(),
      assignmentStatus: zod.string(),
      revision: zod.number(),
      submittedAt: zod.string().nullable(),
      baselineId: zod.string().nullable(),
      instrumentVersion: zod.string(),
      scoringVersion: zod.string(),
      selectedDomains: zod.array(zod.string()),
      context: zod.record(zod.string(), zod.unknown()),
      domains: zod.array(
        zod.object({
          id: zod.string(),
          name: zod.string(),
          status: zod.string(),
          mean: zod.number().nullable(),
          coverage: zod.number().nullable(),
          validCount: zod.number(),
          applicableCount: zod.number(),
          notObservedCount: zod.number(),
          notApplicableCount: zod.number(),
          unansweredCount: zod.number(),
          ratingCounts: zod.record(zod.string(), zod.number()),
          evidence: zod.object({
            impact: zod.number().nullable(),
            examples: zod.array(zod.string()),
            strengths: zod.string(),
            supports: zod.string(),
          }),
          itemResponses: zod.array(
            zod.object({
              itemId: zod.string(),
              wording: zod.string(),
              status: zod.enum([
                "rated",
                "not_observed",
                "not_applicable",
                "unanswered",
              ]),
              value: zod.number().nullable(),
              reason: zod.string().nullable(),
            }),
          ),
        }),
      ),
    }),
  ),
  comparison: zod.union([
    zod.object({
      caseId: zod.string(),
      parentAssignmentId: zod.string(),
      teacherAssignmentId: zod.string(),
      parentRevision: zod.number(),
      teacherRevision: zod.number(),
      generatedAt: zod.date(),
      content: zod.object({
        overallSummary: zod.string(),
        parentHome: zod.string(),
        teacherClassroom: zod.string(),
        crossSetting: zod.string(),
        recommendations: zod.array(zod.string()),
        limitations: zod.string(),
      }),
      stale: zod.boolean(),
    }),
    zod.null(),
  ]),
});

/**
 * @summary Generate and save a DeepSeek comparison draft from one parent and one teacher submission
 */
export const GenerateChineseLiteracyDashboardComparisonParams = zod.object({
  caseId: zod.coerce.string(),
});

export const GenerateChineseLiteracyDashboardComparisonBody = zod.object({
  parentAssignmentId: zod.string().min(1),
  teacherAssignmentId: zod.string().min(1),
});

export const GenerateChineseLiteracyDashboardComparisonResponse = zod.object({
  caseId: zod.string(),
  parentAssignmentId: zod.string(),
  teacherAssignmentId: zod.string(),
  parentRevision: zod.number(),
  teacherRevision: zod.number(),
  generatedAt: zod.date(),
  content: zod.object({
    overallSummary: zod.string(),
    parentHome: zod.string(),
    teacherClassroom: zod.string(),
    crossSetting: zod.string(),
    recommendations: zod.array(zod.string()),
    limitations: zod.string(),
  }),
  stale: zod.boolean(),
});

/**
 * @summary Translate a current combined report for single-language printing
 */
export const TranslateChineseLiteracyDashboardParams = zod.object({
  caseId: zod.coerce.string(),
});

export const TranslateChineseLiteracyDashboardBody = zod.object({
  parentAssignmentId: zod.string().min(1),
  teacherAssignmentId: zod.string().min(1),
  targetLanguage: zod.enum(["en", "zh"]),
});

export const TranslateChineseLiteracyDashboardResponse = zod.object({
  translations: zod.record(zod.string(), zod.string()),
});
